package com.smartseating.dao;

import com.smartseating.model.Seating;
import com.smartseating.util.DBConnection;
import java.sql.*;
import java.util.*;

public class SeatingDAO {
    private Seating map(ResultSet r)throws SQLException{Seating s=new Seating();s.setId(r.getInt("id"));s.setExamId(r.getInt("exam_id"));s.setStudentId(r.getInt("student_id"));s.setRoomId(r.getInt("room_id"));s.setRowLabel(r.getString("row_label"));s.setColumnNumber(r.getInt("column_number"));s.setSeatNumber(r.getString("seat_number"));s.setInvigilatorId(r.getInt("invigilator_id"));s.setRegisterNumber(r.getString("register_number"));s.setStudentName(r.getString("student_name"));s.setDepartmentCode(r.getString("department_code"));s.setSemesterNumber(r.getString("semester_number"));s.setRoomNumber(r.getString("room_number"));s.setInvigilatorName(r.getString("invigilator_name"));return s;}
    private static final String BASE="SELECT s.*,st.register_number,st.name student_name,st.department_code,st.semester_number,r.room_number,COALESCE(t.name,'Unassigned') invigilator_name FROM seating s JOIN students st ON st.id=s.student_id JOIN rooms r ON r.id=s.room_id LEFT JOIN teachers t ON t.id=s.invigilator_id ";
    public void replaceAll(int examId,List<Seating> seats)throws SQLException{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement del=c.prepareStatement("DELETE FROM seating WHERE exam_id=?")){del.setInt(1,examId);del.executeUpdate();}String sql="INSERT INTO seating(exam_id,student_id,room_id,row_label,column_number,seat_number,invigilator_id) VALUES(?,?,?,?,?,?,NULL)";try(PreparedStatement p=c.prepareStatement(sql)){for(Seating s:seats){p.setInt(1,examId);p.setInt(2,s.getStudentId());p.setInt(3,s.getRoomId());p.setString(4,s.getRowLabel());p.setInt(5,s.getColumnNumber());p.setString(6,s.getSeatNumber());p.addBatch();}p.executeBatch();}c.commit();}catch(SQLException e){c.rollback();throw e;}}}
    public void clearExam(int examId)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM seating WHERE exam_id=?")){p.setInt(1,examId);p.executeUpdate();}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM invigilator_assignments WHERE exam_id=?")){p.setInt(1,examId);p.executeUpdate();}}
    public List<Seating> findByExam(int examId)throws SQLException{return query(BASE+"WHERE s.exam_id=? ORDER BY r.room_number,s.row_label,s.column_number",examId);}
    public List<Seating> findByExamRoom(int examId,String roomNumber)throws SQLException{String sql=BASE+"WHERE s.exam_id=? AND r.room_number=? ORDER BY s.row_label,s.column_number";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,examId);p.setString(2,roomNumber);List<Seating>a=new ArrayList<>();try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}return a;}}
    public Seating findByStudent(String registerNumber)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(BASE+"WHERE st.register_number=? ORDER BY s.exam_id DESC LIMIT 1")){p.setString(1,registerNumber);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
    public List<Seating> query(String sql,int examId)throws SQLException{List<Seating>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setInt(1,examId);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}return a;}
    public long countForExam(int examId)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM seating WHERE exam_id=?")){p.setInt(1,examId);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
}
